sys_script_include.script:
var PricingUtils = Class.create();
PricingUtils.prototype = {
    initialize: function() {},

    /**
     * Checks if a room record or room sys_id is currently under maintenance.
     * Normalizes both choice value, display value, and maintenance room names.
     */
    isRoomUnderMaintenance: function(roomGrOrId) {
        var roomGr = null;
        if (typeof roomGrOrId === 'object' && roomGrOrId !== null && typeof roomGrOrId.getValue === 'function') {
            roomGr = roomGrOrId;
        } else if (roomGrOrId) {
            roomGr = new GlideRecord('x_2206701_hotel_0_rooms');
            if (!roomGr.get(String(roomGrOrId))) {
                return false;
            }
        } else {
            return false;
        }
        var val = (roomGr.getValue('availability_status') || '').toLowerCase();
        var disp = (roomGr.getDisplayValue('availability_status') || '').toLowerCase();
        var name = (roomGr.getValue('room_name') || '').toLowerCase();
        return val === 'maintenance' || disp === 'maintenance' || name.indexOf('maintenance') > -1;
    },

    /**
     * 1. ROOM AVAILABILITY & CONFLICT CHECKING
     */
    isRoomAvailable: function(roomId, checkInStr, checkOutStr, excludeResId) {
        if (!roomId || !checkInStr || !checkOutStr) {
            return { available: false, reason: "Room, check-in, and check-out dates are required." };
        }

        var roomGr = new GlideRecord('x_2206701_hotel_0_rooms');
        if (!roomGr.get(roomId)) {
            return { available: false, reason: "Room record not found." };
        }
        if (this.isRoomUnderMaintenance(roomGr)) {
            return { available: false, reason: "This room is currently under maintenance." };
        }

        var resGr = new GlideRecord('x_2206701_hotel_0_scheduled_reservations');
        resGr.addQuery('room', roomId);
        resGr.addQuery('check_in_date', '<', checkOutStr);
        resGr.addQuery('check_out_date', '>', checkInStr);
        resGr.addQuery('reservation_status', 'NOT IN', 'cancelled,checked_out,closed');
        if (excludeResId) {
            resGr.addQuery('sys_id', '!=', excludeResId);
        }
        resGr.query();
        if (resGr.hasNext()) {
            return { available: false, reason: "Room is already booked for the selected dates." };
        }

        return { available: true, reason: "Room is available." };
    },

    /**
     * 2. CURRENT-DAY ROOM AVAILABILITY
     */
    getCurrentDayAvailableRooms: function() {
        var today = new GlideDate().getValue();
        var tomorrow = new GlideDate();
        tomorrow.addDaysLocalTime(1);
        var tomorrowStr = tomorrow.getValue();

        var availableRooms = [];
        var roomGr = new GlideRecord('x_2206701_hotel_0_rooms');
        roomGr.query();

        while (roomGr.next()) {
            if (this.isRoomUnderMaintenance(roomGr)) {
                continue;
            }
            var roomId = roomGr.getUniqueValue();
            var check = this.isRoomAvailable(roomId, today, tomorrowStr);
            if (check.available) {
                availableRooms.push({
                    sys_id: roomId,
                    room_name: roomGr.getValue('room_name'),
                    room_type: roomGr.getDisplayValue('room_type'),
                    capacity: roomGr.getValue('capacity'),
                    rate: parseFloat(roomGr.getValue('rate')) || 0
                });
            }
        }
        return availableRooms;
    },

    /**
     * 3. PRICING & EVENT-BASED DISCOUNT CALCULATION
     */
    calculateRoomTotal: function(roomId, numberOfDays, checkInStr) {
        var roomGr = new GlideRecord('x_2206701_hotel_0_rooms');
        if (!roomGr.get(roomId) || this.isRoomUnderMaintenance(roomGr)) {
            return 0;
        }

        var baseRate = parseFloat(roomGr.getValue('rate')) || 0;
        if (numberOfDays <= 0 || !checkInStr) {
            return baseRate * (numberOfDays > 0 ? numberOfDays : 1);
        }

        var total = 0;
        var currentDate = new GlideDate();
        currentDate.setValue(checkInStr);

        for (var i = 0; i < numberOfDays; i++) {
            var dateStr = currentDate.getValue();
            var discountPct = this.getDiscountPercentageForDate(dateStr);
            var nightCost = baseRate;
            if (discountPct > 0) {
                nightCost = baseRate * (1 - (discountPct / 100));
            }
            total += nightCost;
            currentDate.addDaysLocalTime(1);
        }

        return Math.round(total * 100) / 100;
    },

    getDiscountPercentageForDate: function(dateStr) {
        var calGr = new GlideRecord('x_2206701_hotel_0_calendar_days');
        calGr.addQuery('date', dateStr);
        calGr.query();
        if (calGr.next()) {
            var pct = parseFloat(calGr.getValue('discount_percentage')) || 0;
            return pct;
        }
        return 0;
    },

    /**
     * 4. SPORTS ACTIVITY PRICING & ENFORCEMENT
     */
    calculateSportsActivity: function(activityId) {
        if (!activityId) {
            return { ok: false, rate: 0, message: "No sports activity selected." };
        }
        var actGr = new GlideRecord('x_2206701_hotel_0_sports_activities');
        if (actGr.get(activityId)) {
            var rate = parseFloat(actGr.getValue('rate')) || 0;
            return {
                ok: true,
                rate: rate,
                activity_name: actGr.getValue('activity_name'),
                message: "Activity rate retrieved successfully."
            };
        }
        return { ok: false, rate: 0, message: "Sports activity not found." };
    },

    validateSingleSportsActivity: function(activities) {
        var count = Array.isArray(activities) ? activities.length : (parseInt(activities, 10) || 0);
        if (count > 1) {
            return {
                valid: false,
                message: "Rule violation: You may only book one (1) sports activity per booking."
            };
        }
        return { valid: true, message: "Valid sports activity selection." };
    },

    /**
     * Upfront validation for sports booking before confirmation modal opens.
     */
    validateSportsActivityBooking: function(reservationNumber, userId, guestEmail, selectedActivityId) {
        var resNum = reservationNumber ? String(reservationNumber).trim() : '';
        if (!resNum) {
            return { valid: false, message: "Please enter your room reservation number." };
        }

        var grRes = new GlideRecord('x_2206701_hotel_0_scheduled_reservations');
        grRes.addQuery('number', resNum);
        grRes.query();
        var found = grRes.next();
        if (!found) {
            found = grRes.get(resNum);
        }

        if (!found) {
            return {
                valid: false,
                message: 'No active room reservation found for "' + resNum + '". A valid room reservation is required to book sports activities.'
            };
        }

        var resStatus = (grRes.getValue('reservation_status') || '').toLowerCase();
        if (resStatus === 'cancelled' || resStatus === 'closed') {
            return {
                valid: false,
                message: 'No active room reservation found for "' + resNum + '". A valid room reservation is required to book sports activities.'
            };
        }

        var resSysId = grRes.getUniqueValue();
        var resDisplayNum = grRes.getValue('number') || resNum;
        var guestName = grRes.getValue('guest_name') || '';
        var resEmail = grRes.getValue('guest_email') || '';
        var resUser = grRes.getValue('registered_user') || '';
        var targetUser = userId || resUser || '';
        var targetEmail = guestEmail || resEmail || '';

        var existingGr = new GlideRecord('x_2206701_hotel_0_sports_bookings');
        existingGr.addQuery('booking_status', '!=', 'cancelled');
        existingGr.addQuery('booking_status', '!=', 'completed');

        var qc = null;
        if (existingGr.isValidField('room_reservation')) {
            qc = existingGr.addQuery('room_reservation', resSysId);
        }
        if (targetUser) {
            if (qc) qc.addOrCondition('registered_user', targetUser);
            else qc = existingGr.addQuery('registered_user', targetUser);
        }
        if (targetEmail) {
            if (qc) qc.addOrCondition('guest_email', targetEmail);
            else qc = existingGr.addQuery('guest_email', targetEmail);
        }
        existingGr.query();

        if (existingGr.next()) {
            this.validateSingleSportsActivity([existingGr.getUniqueValue(), selectedActivityId || 'new']);
            return {
                valid: false,
                message: 'A sports activity is already scheduled for this stay (' + (existingGr.getValue('number') || 'existing') + '). Only one activity is permitted per booking.'
            };
        }

        return {
            valid: true,
            reservationSysId: resSysId,
            reservationNumber: resDisplayNum,
            guestName: guestName,
            guestEmail: targetEmail,
            registeredUser: targetUser,
            message: "Valid sports activity selection."
        };
    },

    type: 'PricingUtils'
};
